import re, sys
R = '/home/user/fortress-landing-35/'
owed = open(R + 'explorations/compile-ladder/climb-batch-35/record-landing/owed.md').read().split('\n')
plan = open(R + 'explorations/coordinator/PLAN.md').read().split('\n')
moves = {}
for l in owed:
    m = re.match(r'- (C\d+) \| home: PLAN\.md:(\d+)(?: to (\d+))?,.*moved to PLAN-history', l)
    if m:
        a = int(m.group(2)); b = int(m.group(3) or a)
        for n in range(a, b + 1):
            moves[n] = m.group(1)
print(len(moves))
# section counts after removal
sec = None; counts = {}
for i, t in enumerate(plan, 1):
    if t.startswith('#'):
        sec = (i, t); counts[sec] = [0, 0]
        continue
    if sec and t.startswith('- '):
        counts[sec][0] += 1
        if i in moves:
            counts[sec][1] += 1
for s, (tot, mv) in counts.items():
    if mv:
        print(s[0], s[1][:60], 'items', tot, 'moved', mv, 'LEFT', tot - mv)
# check each moved line starts with '- ' or digit
for n in sorted(moves):
    t = plan[n - 1]
    if not (t.startswith('- ') or re.match(r'\d+\. ', t)):
        print('ODD', n, t[:80])

